import datetime
import logging
import time
import traceback
import os
from taf.internal.robot_typecasts import time_to_seconds


def get_relative_path(absolute_path, base_path):
    """
    Get relative path from absolute_path to base_path.
    :param absolute_path: The absolute path to convert.
    :param base_path: The base path to which the relative path is calculated.
    :return: Relative path from base_path to absolute_path.
    """
    return os.path.relpath(path=absolute_path, start=base_path)


def safe_call(func, *args, default_value="", log_warn=True, **kwargs):
    """
    Call function and catch exception. If exception occurs, log it and return default_value.
    """
    log_method = logging.warning if log_warn else logging.debug
    try:
        return func(*args, **kwargs)
    except Exception as e:
        log_method(f"Call {func.__name__} failed with args: {args}, kwargs: {kwargs}")
        logging.debug("\tException: {}".format(repr(e)))
        return default_value


def get_formatted_traceback(exception):
    """
    Returns the formatted traceback of the given exception as a string.
    """
    return ''.join(traceback.format_exception(type(exception), exception, exception.__traceback__))


def wait_till_succeeds(func, exception_to_catch, interval=30, timeout=300, print_traceback=False,
                       *args, **kwargs):
    """
    Calls the function until it succeeds (does not raise an exception) or the timeout is reached.
    :param func: The function to call.
    :param exception_to_catch: The exception to catch and retry on. Can be a single exception or a tuple of exceptions.
    :param interval: The interval between retries in seconds.
    :param timeout: The maximum time to wait in seconds.
    :param print_traceback: If True, prints the traceback of the caught exception to the log.
    :param args: The positional arguments to pass to the function.
    :param kwargs: The keyword arguments to pass to the function.
    """
    if not isinstance(exception_to_catch, (tuple, list)):
        exception_to_catch = (exception_to_catch,)

    start_time = time.monotonic()
    end_time = start_time + time_to_seconds(time=timeout)
    interval = time_to_seconds(time=interval)
    attempt = 0
    logging.info(f"Calling function {func.__name__} with args={args}, kwargs={kwargs} with timeout {timeout} seconds "
                 f"and interval {interval} seconds")
    while time.monotonic() < end_time:
        attempt += 1
        logging.debug(f"Attempt number {attempt}")
        try:
            return func(*args, **kwargs)
        except exception_to_catch as e:
            logging.info(f"Attempt {attempt} failed")
            if print_traceback:
                logging.debug("\tDetails: {}".format(get_formatted_traceback(e)))
            current_time = time.monotonic()
            logging.debug("Time elapsed: {:.2f} seconds".format(current_time - start_time))
            logging.debug("Time remaining: {:.2f} seconds".format(end_time - current_time))
            logging.info(f"Waiting {interval} seconds for next attempt...")
            time.sleep(interval)
    raise TimeoutError(f"Function {func.__name__} did not succeed within {timeout} seconds")


def get_difference_between_lists(first_list, second_list):
    """
    Returns the list of items that are not present in first_list
    :param first_list: The list with which the comparison is going to be made against
    :param second_list: The new items in this list which are not present in first_list needs to be found
    :return: List of items that are not present in first_list
    contact : gopalakrishnan.n@nokia.com
        """
    return list(set(second_list).difference(set(first_list)))


def get_timestamp():
    """
    Returns the current timestamp in the format [YYYY-MM-DD HH:MM:SS].
    """
    return "[{}]".format(datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'))


def get_variables_from_python_file(file_path):
    """
    Get all variables from a python file as a dictionary.
    :param file_path: path to the python file
    :return: dictionary of variables
    """
    variables = {}
    with open(file_path, 'r') as f:
        code = f.read()
    exec(code, {}, variables)
    return {k: v for k, v in variables.items() if not k.startswith('_')}


def return_all_key_paths_and_values_from_iterable(iterable, path_to_value=''):
    """
    author:         Grzegorz Kaczor, grzegorz.kaczor@nokia.com
    maintainer:     Grzegorz Kaczor, grzegorz.kaczor@nokia.com
    """
    all_values = []
    sub_elements = [iterable]
    while sub_elements:
        element = sub_elements.pop()
        if isinstance(element, list):
            sub_elements.extend(element)
        if isinstance(element, dict):
            for found_key, value in element.items():
                if isinstance(value, list) or isinstance(value, dict):
                    all_values.extend(return_all_key_paths_and_values_from_iterable(value,
                                                                                    path_to_value + ": {} ".format(
                                                                                        found_key)))
                else:
                    all_values.append((path_to_value + ": {} ".format(found_key), value))
    return all_values
